package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class GroupMyAssignmentsIntegrationTest {
 SubmissionStoreIntegrationTest f;GroupMyAssignmentsStore store;
 @BeforeEach void setup(){f=new SubmissionStoreIntegrationTest();f.setup();store=new GroupMyAssignmentsStore(f.f.source,new GroupStore(f.f.source,Clock.systemUTC()));}
 GroupMyAssignmentsStore.Page list(String filter,UUID after,int limit){return store.list(f.group,f.space,f.author,after,limit,filter);}
 GroupMyAssignmentsStore.Row row(){return list("ALL",null,100).items().stream().filter(v->v.assignmentId().equals(f.assignment)).findFirst().orElseThrow();}
 UUID task(String state){UUID id=f.parent.create(f.f.key()).assignment().assignmentId();if(!state.equals("DRAFT"))f.parent.store.state(f.group,f.space,f.study,id,f.f.owner,1,"OPEN",f.f.trace);if(state.equals("CLOSED")||state.equals("RETIRED"))f.parent.store.state(f.group,f.space,f.study,id,f.f.owner,2,state,f.f.trace);return id;}
 @Test void absenceAndSharedDraftReadCreateNoSubmissionOrEvent(){
  int before=f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);assertTrue(list("OPEN_NOT_SUBMITTED",null,20).items().isEmpty());assertEquals("DRAFT",row().state());assertNull(row().submissionId());assertNull(row().submissionVersion());assertNull(row().submittedAssignmentVersion());assertNull(f.store.mine(f.group,f.space,f.study,f.assignment,f.author,false).submission());assertEquals(before,f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));f.open();assertEquals(1,list("OPEN_NOT_SUBMITTED",null,20).items().size());var json=tools.jackson.databind.json.JsonMapper.builder().build().valueToTree(row());assertEquals(10,json.size());for(String key:List.of("authorId","content","score","reason","total","canSubmit","description"))assertFalse(json.has(key));
 }
 @Test void ownPresenceNeverInheritsPeerOrOwnerSubmission(){
  f.open();UUID peer=f.f.ids.next();var other=f.store.submit(f.group,f.space,f.study,f.assignment,peer,0,2,f.f.key(),"PEER SECRET ANSWER",f.f.trace).submission();assertNull(row().submissionId());assertEquals(1,list("OPEN_NOT_SUBMITTED",null,20).items().size());var ownOwner=f.store.submit(f.group,f.space,f.study,f.assignment,f.f.owner,0,2,f.f.key(),"OWNER SECRET ANSWER",f.f.trace).submission();assertNull(row().submissionId());assertEquals(other.submissionId(),store.list(f.group,f.space,peer,null,20,"ALL").items().getFirst().submissionId());assertEquals(ownOwner.submissionId(),store.list(f.group,f.space,f.f.owner,null,20,"ALL").items().getFirst().submissionId());var mine=f.submit(f.f.key(),0,2,"MY PRIVATE ANSWER").submission();assertEquals(mine.submissionId(),row().submissionId());assertTrue(list("OPEN_NOT_SUBMITTED",null,20).items().isEmpty());assertEquals(1,list("SUBMITTED",null,20).items().size());assertTrue(list("NOT_SUBMITTED",null,20).items().isEmpty());
 }
 @Test void currentDefinitionAndOwnSubmissionVersionsRemainIndependent(){
  f.open();var mine=f.submit(f.f.key(),0,2,"First").submission();f.parent.store.metadata(f.group,f.space,f.study,f.assignment,f.f.owner,2,"New <script> instructions","Shared new content",f.f.trace);assertEquals(3,row().version());assertEquals("New <script> instructions",row().title());assertEquals(2L,row().submittedAssignmentVersion());assertEquals(1L,row().submissionVersion());f.submit(f.f.key(),1,3,"Second");assertEquals(mine.submissionId(),row().submissionId());assertEquals(2L,row().submissionVersion());assertEquals(3L,row().submittedAssignmentVersion());assertEquals(3,row().version());
 }
 @Test void assignmentStatesAndStudyArchiveAreFilteredWithoutReopeningOrCompletion(){
  UUID open=task("OPEN"),closed=task("CLOSED"),retired=task("RETIRED");assertEquals(4,list("ALL",null,100).items().size());assertEquals(List.of(open),list("OPEN_NOT_SUBMITTED",null,20).items().stream().map(GroupMyAssignmentsStore.Row::assignmentId).toList());f.store.submit(f.group,f.space,f.study,open,f.author,0,2,f.f.key(),"ANSWER",f.f.trace);assertTrue(list("OPEN_NOT_SUBMITTED",null,20).items().isEmpty());assertEquals(1,list("OPEN",null,20).items().size());assertEquals(1,list("SUBMITTED",null,20).items().size());assertEquals(3,list("NOT_SUBMITTED",null,20).items().size());assertTrue(list("NOT_SUBMITTED",null,20).items().stream().anyMatch(v->v.assignmentId().equals(closed)));assertTrue(list("NOT_SUBMITTED",null,20).items().stream().anyMatch(v->v.assignmentId().equals(retired)));
  f.parent.parent.store.state(f.group,f.space,f.study,f.f.owner,1,"ACTIVE",f.f.trace);f.parent.parent.store.state(f.group,f.space,f.study,f.f.owner,2,"COMPLETED",f.f.trace);assertEquals("COMPLETED",list("OPEN",null,20).items().getFirst().studyState());f.parent.parent.store.state(f.group,f.space,f.study,f.f.owner,3,"RETIRED",f.f.trace);int before=f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);assertTrue(list("OPEN",null,20).items().isEmpty());assertTrue(list("OPEN_NOT_SUBMITTED",null,20).items().isEmpty());assertEquals(4,list("ALL",null,100).items().size());for(String filter:GroupMyAssignmentsStore.FILTERS)for(var v:list(filter,null,100).items())assertEquals("RETIRED",v.studyState());assertEquals(before,f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));
 }
 @Test void keysetAppliesOwnPresenceAndStateBeforeLimit(){
  for(int n=0;n<12;n++){UUID id=task(n%3==0?"DRAFT":"OPEN");if(n%3==1)f.store.submit(f.group,f.space,f.study,id,f.author,0,2,f.f.key(),"MY ANSWER",f.f.trace);if(n%3==2)f.store.submit(f.group,f.space,f.study,id,f.f.ids.next(),0,2,f.f.key(),"PEER ANSWER",f.f.trace);}
  assertEquals(13,list("ALL",null,100).items().size());assertEquals(4,list("OPEN_NOT_SUBMITTED",null,100).items().size());var seen=new ArrayList<UUID>();UUID after=null;do{var p=list("OPEN_NOT_SUBMITTED",after,2);seen.addAll(p.items().stream().map(GroupMyAssignmentsStore.Row::assignmentId).toList());after=p.nextAfter();}while(after!=null);assertEquals(list("OPEN_NOT_SUBMITTED",null,100).items().stream().map(GroupMyAssignmentsStore.Row::assignmentId).toList(),seen);assertEquals(4,new HashSet<>(seen).size());
 }
 @Test void foreignGroupSpacePendingEmptyAndInvalidBoundsStayClosed(){
  f.status(404,()->store.list(f.f.ids.next(),f.space,f.author,null,20,"ALL"));f.status(404,()->store.list(f.group,f.f.ids.next(),f.author,null,20,"ALL"));var groups=new GroupStore(f.f.source,Clock.systemUTC());var g=groups.request(f.f.owner,f.f.key(),"Empty Group","",f.f.trace);UUID space=f.f.ids.next();f.status(404,()->store.list(g.groupId(),space,f.author,null,20,"ALL"));groups.activate(g.groupId(),f.f.owner,space,f.f.trace);assertTrue(store.list(g.groupId(),space,f.author,null,20,"ALL").items().isEmpty());for(int limit:List.of(0,101))f.status(400,()->list("ALL",null,limit));for(String filter:List.of("open","CURRENT","REQUESTED","","SUBMITTED' OR TRUE--"))f.status(400,()->list(filter,null,20));
 }
 @Test void concurrentResubmissionAndAssignmentEditUseOneStatementSnapshot()throws Exception{
  f.open();f.submit(f.f.key(),0,2,"Original");try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CyclicBarrier(2);var reader=pool.submit(()->{barrier.await();for(int n=0;n<30;n++){var v=row();assertNotNull(v.submissionId());assertTrue(v.submittedAssignmentVersion()<=v.version());if(v.submissionVersion()==2){assertEquals(3L,v.submittedAssignmentVersion());assertEquals(3,v.version());}}return true;});var writer=pool.submit(()->{barrier.await();f.parent.store.metadata(f.group,f.space,f.study,f.assignment,f.f.owner,2,"Revised","New",f.f.trace);return f.submit(f.f.key(),1,3,"New answer");});assertTrue(reader.get(20,TimeUnit.SECONDS));assertTrue(writer.get(20,TimeUnit.SECONDS).applied());assertEquals(2L,row().submissionVersion());}
 }
 @Test void assignmentCloseBetweenReadsDoesNotChangeSubmissionOrGrantWrite(){
  f.open();var answer=f.submit(f.f.key(),0,2,"PRIVATE").submission();f.parent.store.state(f.group,f.space,f.study,f.assignment,f.f.owner,2,"CLOSED",f.f.trace);int before=f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);assertTrue(list("OPEN",null,20).items().isEmpty());assertEquals("CLOSED",row().state());assertEquals(answer.submissionId(),row().submissionId());assertEquals(answer,f.store.get(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.author,false));assertFalse(f.store.mine(f.group,f.space,f.study,f.assignment,f.author,true).canSubmit());assertEquals(before,f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));
 }

 UUID task(UUID study){UUID id=f.parent.store.create(f.group,f.space,study,f.f.owner,f.f.key(),"Task <script>","Shared",f.f.trace).assignment().assignmentId();f.parent.store.state(f.group,f.space,study,id,f.f.owner,1,"OPEN",f.f.trace);return id;}
 @Test void allStudiesUseCurrentLabelsAndOwnFilteredKeysetWithoutCourseRequirement(){
  var b=f.parent.parent.create(f.f.key()).study();for(int n=0;n<12;n++){UUID study=n%2==0?f.study:b.studyId(),id=task(study);f.store.submit(f.group,f.space,study,id,n%2==0?f.author:f.f.ids.next(),0,2,f.f.key(),"PRIVATE ANSWER",f.f.trace);}assertEquals(13,list("ALL",null,100).items().size());assertEquals(6,list("OPEN_NOT_SUBMITTED",null,100).items().size());assertEquals(6,list("SUBMITTED",null,100).items().size());f.parent.parent.store.metadata(f.group,f.space,b.studyId(),f.f.owner,1,"Current B <script>","Shared",f.f.trace);assertTrue(list("ALL",null,100).items().stream().filter(v->v.studyId().equals(b.studyId())).allMatch(v->v.studyTitle().equals("Current B <script>")));var seen=new ArrayList<UUID>();UUID after=null;do{var p=list("OPEN_NOT_SUBMITTED",after,2);seen.addAll(p.items().stream().map(GroupMyAssignmentsStore.Row::assignmentId).toList());after=p.nextAfter();}while(after!=null);assertEquals(list("OPEN_NOT_SUBMITTED",null,100).items().stream().map(GroupMyAssignmentsStore.Row::assignmentId).toList(),seen);assertEquals(6,new HashSet<>(seen).size());assertEquals(0,f.f.jdbc.queryForObject("SELECT count(*) FROM group_course WHERE group_id=?",Integer.class,f.group));f.parent.parent.store.state(f.group,f.space,b.studyId(),f.f.owner,2,"RETIRED",f.f.trace);int events=f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);assertTrue(list("OPEN_NOT_SUBMITTED",null,100).items().isEmpty());assertEquals(13,list("ALL",null,100).items().size());for(String filter:GroupMyAssignmentsStore.FILTERS)list(filter,null,100);assertEquals(events,f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));
 }
 @Test void foreignGroupAssignmentsAndOwnSubmissionsStayInTheirExactSpace(){
  var groups=new GroupStore(f.f.source,Clock.systemUTC());var g=groups.request(f.f.owner,f.f.key(),"Other Group","",f.f.trace);UUID space=f.f.ids.next();groups.activate(g.groupId(),f.f.owner,space,f.f.trace);UUID study=new StudyStore(f.f.source,Clock.systemUTC()).create(g.groupId(),space,f.f.owner,f.f.key(),"Foreign Study","",f.f.trace).study().studyId();UUID assignment=f.parent.store.create(g.groupId(),space,study,f.f.owner,f.f.key(),"Foreign Assignment","",f.f.trace).assignment().assignmentId();f.parent.store.state(g.groupId(),space,study,assignment,f.f.owner,1,"OPEN",f.f.trace);var own=f.store.submit(g.groupId(),space,study,assignment,f.author,0,2,f.f.key(),"FOREIGN PRIVATE ANSWER",f.f.trace).submission();assertEquals(1,list("ALL",null,100).items().size());assertTrue(list("ALL",null,100).items().stream().noneMatch(v->v.assignmentId().equals(assignment)));assertEquals(own.submissionId(),store.list(g.groupId(),space,f.author,null,20,"ALL").items().getFirst().submissionId());
 }
}
